1	// Shared plan constants — safe for both client and server
2	
3	/**
4	 * Sentinel value used in place of Infinity for "unlimited" plan limits.
5	 * Infinity cannot be serialized to JSON (becomes null), so we use this
6	 * large number as the canonical "no limit" value. All limit comparisons
7	 * should use isUnlimited() or compare against UNLIMITED.
8	 */
9	export const UNLIMITED = 999999;
10	
11	export const PLAN_FREE = "free";
12	export const PLAN_STARTER_MONTHLY = "Starter Monthly";
13	export const PLAN_STARTER_ANNUAL = "Starter Annual";
14	export const PLAN_PRO_MONTHLY = "Pro Monthly";
15	export const PLAN_PRO_ANNUAL = "Pro Annual";
16	export const PLAN_ULTIMATE_MONTHLY = "Ultimate Monthly";
17	export const PLAN_ULTIMATE_ANNUAL = "Ultimate Annual";
18	
19	export const ALL_PAID_PLANS = [
20	  PLAN_STARTER_MONTHLY,
21	  PLAN_STARTER_ANNUAL,
22	  PLAN_PRO_MONTHLY,
23	  PLAN_PRO_ANNUAL,
24	  PLAN_ULTIMATE_MONTHLY,
25	  PLAN_ULTIMATE_ANNUAL,
26	];
27	
28	export type PlanTier = "free" | "starter" | "pro" | "ultimate";
29	
30	export interface PlanLimits {
31	  maxZipCodes: number;
32	  allowBlocked: boolean;
33	  maxDeliveryRules: number;
34	  maxWaitlist: number;
35	  csvImport: boolean;
36	  csvExport: boolean;
37	  widgetBasicCustom: boolean;
38	  widgetFullCustom: boolean;
39	  showEtaCodReturn: boolean;
40	  cartBlocking: boolean;
41	  customCss: boolean;
42	  productCollectionRules: boolean;
43	  label: string;
44	}
45	
46	export const PLAN_LIMITS: Record<PlanTier, PlanLimits> = {
47	  free: {
48	    maxZipCodes: 20,
49	    allowBlocked: false,
50	    maxDeliveryRules: 0,
51	    maxWaitlist: 0,
52	    csvImport: false,
53	    csvExport: false,
54	    widgetBasicCustom: true,
55	    widgetFullCustom: false,
56	    showEtaCodReturn: false,
57	    cartBlocking: false,
58	    customCss: false,
59	    productCollectionRules: false,
60	    label: "Free",
61	  },
62	  starter: {
63	    maxZipCodes: 500,
64	    allowBlocked: true,
65	    maxDeliveryRules: 3,
66	    maxWaitlist: 50,
67	    csvImport: true,
68	    csvExport: false,
69	    widgetBasicCustom: true,
70	    widgetFullCustom: true,
71	    showEtaCodReturn: true,
72	    cartBlocking: false,
73	    customCss: false,
74	    productCollectionRules: false,
75	    label: "Starter",
76	  },
77	  pro: {
78	    maxZipCodes: UNLIMITED,
79	    allowBlocked: true,
80	    maxDeliveryRules: UNLIMITED,
81	    maxWaitlist: UNLIMITED,
82	    csvImport: true,
83	    csvExport: true,
84	    widgetBasicCustom: true,
85	    widgetFullCustom: true,
86	    showEtaCodReturn: true,
87	    cartBlocking: true,
88	    customCss: false,
89	    productCollectionRules: true,
90	    label: "Pro",
91	  },
92	  ultimate: {
93	    maxZipCodes: UNLIMITED,
94	    allowBlocked: true,
95	    maxDeliveryRules: UNLIMITED,
96	    maxWaitlist: UNLIMITED,
97	    csvImport: true,
98	    csvExport: true,
99	    widgetBasicCustom: true,
100	    widgetFullCustom: true,
101	    showEtaCodReturn: true,
102	    cartBlocking: true,
103	    customCss: true,
104	    productCollectionRules: true,
105	    label: "Ultimate",
106	  },
107	};
108	
109	export function getPlanTier(planName: string): PlanTier {
110	  if (planName === PLAN_STARTER_MONTHLY || planName === PLAN_STARTER_ANNUAL)
111	    return "starter";
112	  if (planName === PLAN_PRO_MONTHLY || planName === PLAN_PRO_ANNUAL)
113	    return "pro";
114	  if (planName === PLAN_ULTIMATE_MONTHLY || planName === PLAN_ULTIMATE_ANNUAL)
115	    return "ultimate";
116	  return "free";
117	}
