33	
34	/** Maximum length for custom CSS (characters). Prevents DB bloat and slow responses. */
35	const MAX_CUSTOM_CSS_LENGTH = 10_000;
36	
37	export const loader = async ({ request }: LoaderFunctionArgs) => {
