45	export const action = async ({ request }: ActionFunctionArgs) => {
46	  if (request.method === "OPTIONS") {
47	    return new Response(null, { status: 204, headers: CORS_HEADERS });
48	  }
49	
50	  if (request.method !== "POST") {
51	    return new Response(JSON.stringify({ error: "Method not allowed" }), {
52	      status: 405,
53	      headers: CORS_HEADERS,
54	    });
55	  }
56	
57	  // Rate limit: 10 signups per IP per minute (write operation — tighter limit)
58	  const ip = getClientIp(request);
59	  const { limited, resetAt } = rateLimit(`waitlist:${ip}`, 10, 60_000);
60	  if (limited) return rateLimitResponse(resetAt, CORS_HEADERS);
61	
62	  let shop: string | null = null;
63	  let zip: string | null = null;
64	  let email: string | null = null;
65	  let name: string | null = null;
66	
67	  try {
68	    const body = await request.json();
69	    shop = body?.shop ?? null;
70	    zip = body?.zip ?? null;
71	    email = body?.email ?? null;
72	    name = body?.name ?? null;
73	  } catch {
74	    return new Response(JSON.stringify({ error: "Invalid JSON body" }), {
75	      status: 400,
76	      headers: CORS_HEADERS,
77	    });
78	  }
79	
80	  if (!shop || !zip || !email) {
81	    return new Response(
82	      JSON.stringify({ error: "Missing required fields: shop, zip, email" }),
83	      { status: 400, headers: CORS_HEADERS },
84	    );
85	  }
86	
87	  // Validate shop is a real myshopify.com domain (prevents cross-shop enumeration)
88	  if (!/^[a-zA-Z0-9][a-zA-Z0-9-]*\.myshopify\.com$/.test(shop) || shop.length > 100) {
89	    return new Response(
90	      JSON.stringify({ error: "Invalid shop parameter" }),
91	      { status: 400, headers: CORS_HEADERS },
92	    );
93	  }
94	
95	  // Enforce input length limits to prevent abuse
96	  if (zip.length > 20 || email.length > 254) {
97	    return new Response(
98	      JSON.stringify({ error: "Invalid input" }),
99	      { status: 400, headers: CORS_HEADERS },
100	    );
101	  }
102	
103	  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
104	    return new Response(
105	      JSON.stringify({ error: "Invalid email address" }),
106	      { status: 400, headers: CORS_HEADERS },
107	    );
108	  }
109	
110	  // Check if shop's plan allows waitlist
111	  try {
112	    const subscription = await getShopSubscription(shop);
113	    if (subscription.limits.maxWaitlist === 0) {
